package com.shale.data.dao;
import static org.junit.jupiter.api.Assertions.*;
import java.lang.reflect.*;
import java.nio.file.*;
import java.sql.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import com.shale.core.model.*;
class ApplicationReleaseReadDaoContractTest {
	@Test void sqlIsGlobalPublishedNumericAndDeterministicallyOrdered()throws Exception{String s=Files.readString(Path.of("src/main/java/com/shale/data/dao/ApplicationReleaseReadDao.java"));assertFalse(s.contains("ShaleClientId"));assertTrue(s.contains("PublicationStatus='PUBLISHED'"));assertTrue(s.contains("MajorVersion>? OR (MajorVersion=? AND MinorVersion>?)"));assertTrue(s.contains("ORDER BY MajorVersion ASC,MinorVersion ASC,BuildVersion ASC"));assertTrue(s.contains("ApplicationReleaseId=? AND IsActive=1 ORDER BY SortOrder ASC,Id ASC"));assertTrue(s.contains("p.IsCurrent=1"));}
	@Test void emptyCurrentPolicyIsExplicitlyEmpty(){var dao=new ApplicationReleaseReadDao(()->connection(new Object[0][]));assertTrue(dao.findCurrentPolicy(ReleaseChannel.PRODUCTION).isEmpty());}
	@Test void releaseRowsMapNumericOrderNullableUrlAndRejectUnknownVocabulary(){var rows=new Object[][]{{1L,1,0,130,"PRODUCTION","PUBLISHED",Timestamp.from(java.time.Instant.EPOCH),"new",new byte[]{1}}};var dao=new ApplicationReleaseReadDao(()->connection(rows));assertEquals("1.0.130",dao.listPublishedReleasesAfter(ReleaseChannel.PRODUCTION,new SemanticVersion(1,0,99)).get(0).version().toString());var bad=new Object[][]{{1L,1,0,130,"UNKNOWN","PUBLISHED",null,"bad",new byte[]{1}}};assertThrows(IllegalStateException.class,()->new ApplicationReleaseReadDao(()->connection(bad)).listPublishedReleasesAfter(ReleaseChannel.PRODUCTION,new SemanticVersion(0,0,0)));}
	@Test void releaseItemRetainsNullableResourceUrl(){var row=new Object[][]{{8L,4L,2,"LINK","title","body",null,true}};var item=new ApplicationReleaseReadDao(()->connection(row)).listReleaseItems(4).get(0);assertNull(item.resourceUrl());assertEquals(2,item.sortOrder());}
	@Test void currentPolicyResolvesPublishedReferencesAndValidatesOrdering(){var dao=new ApplicationReleaseReadDao(()->connection(new Object[][]{policy("PRODUCTION","PUBLISHED",130,127,99)}));var policy=dao.findCurrentPolicy(ReleaseChannel.PRODUCTION).orElseThrow();assertEquals("1.0.130",policy.latest().version().toString());assertEquals("1.0.99",policy.minimumAllowed().version().toString());}
	@Test void currentPolicyRejectsWrongChannelDraftAndInvalidMinimums(){assertPolicyRejected(policy("PILOT","PUBLISHED",130,127,99));assertPolicyRejected(policy("PRODUCTION","DRAFT",130,127,99));assertPolicyRejected(policy("PRODUCTION","PUBLISHED",130,127,140));assertPolicyRejected(policy("PRODUCTION","PUBLISHED",130,140,99));}
	private static void assertPolicyRejected(Object[] row){assertThrows(IllegalStateException.class,()->new ApplicationReleaseReadDao(()->connection(new Object[][]{row})).findCurrentPolicy(ReleaseChannel.PRODUCTION));}
	private static Object[] policy(String releaseChannel,String status,int latest,int recommended,int allowed){Timestamp now=Timestamp.from(java.time.Instant.EPOCH);return new Object[]{5L,"PRODUCTION",2L,null,"NORMAL",now,new byte[]{1},10L,1,0,latest,releaseChannel,status,11L,1,0,recommended,"PRODUCTION","PUBLISHED",12L,1,0,allowed,"PRODUCTION","PUBLISHED",now};}
	private static Connection connection(Object[][] rows){return proxy(Connection.class,(m,a)->switch(m.getName()){case"prepareStatement"->statement(rows);case"close"->null;default->value(m.getReturnType());});}
	private static PreparedStatement statement(Object[][] rows){return proxy(PreparedStatement.class,(m,a)->switch(m.getName()){case"setString","setInt","setLong","close"->null;case"executeQuery"->result(rows);default->value(m.getReturnType());});}
	private static ResultSet result(Object[][] rows){int[] i={-1};return proxy(ResultSet.class,(m,a)->switch(m.getName()){case"next"->++i[0]<rows.length;case"getObject"->rows[i[0]][(int)a[0]-1];case"getLong"->((Number)rows[i[0]][(int)a[0]-1]).longValue();case"getInt"->((Number)rows[i[0]][(int)a[0]-1]).intValue();case"getString"->{Object v=rows[i[0]][(int)a[0]-1];yield v==null?null:v.toString();}case"getTimestamp"->rows[i[0]][(int)a[0]-1];case"getBytes"->rows[i[0]][(int)a[0]-1];case"getBoolean"->rows[i[0]][(int)a[0]-1];case"close"->null;default->value(m.getReturnType());});}
	@SuppressWarnings("unchecked")private static <T>T proxy(Class<T> type,Call call){return(T)Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},(p,m,a)->call.run(m,a));}interface Call{Object run(Method m,Object[]a)throws Throwable;}private static Object value(Class<?>t){if(!t.isPrimitive())return null;if(t==boolean.class)return false;if(t==int.class)return 0;if(t==long.class)return 0L;return null;}
}
